const l="/dashboard/atividades-recentes-csv";async function p(){const e=document.getElementById("atividades-recentes-container");if(e)try{const t=await fetch(l,{headers:{Accept:"text/csv"}});if(!t.ok)throw new Error("Falha ao carregar atividades");const n=await t.text(),c=u(n);f(e,c)}catch{e.innerHTML='<div class="card-body"><p style="color:var(--text-3)">Nao foi possivel carregar Atividades Recentes</p></div>'}}function h(e){const t=[];let n="",c=!1;for(let r=0;r<e.length;r++){const a=e[r];c?a==='"'&&e[r+1]==='"'?(n+='"',r++):a==='"'?c=!1:n+=a:a==='"'?c=!0:a===","?(t.push(n),n=""):n+=a}return t.push(n),t}function u(e){return e.split(/\r?\n/).filter(t=>t.trim()!=="").map(h)}function f(e,t){if(!t.length){e.innerHTML='<div class="card-body"><p style="color:var(--text-3)">Nenhuma atividade registrada</p></div>';return}const n=document.createElement("table");n.className="table";const c=document.createElement("thead"),r=document.createElement("tr");t[0].forEach(s=>{const d=document.createElement("th");d.textContent=s,r.appendChild(d)}),c.appendChild(r),n.appendChild(c);const a=document.createElement("tbody");t.slice(1).forEach(s=>{const d=document.createElement("tr");s.forEach(o=>{const i=document.createElement("td");i.textContent=o,d.appendChild(i)}),a.appendChild(d)}),n.appendChild(a),e.innerHTML="",e.appendChild(n)}function m(){p()}export{m as initAtividadesRecentes};
